// Kant D. Bugg is operating a coffee shop on his own! He wants to find how many cups of coffee he needs to sell in order to turn a profit. Every cup of coffee uses 1/100 gallon of milk, 1/150 bag of beans, and 1/200 sack of sugar. At the end of the day, all the ingredients go bad! He will also need to pay for cups, maintenance, and rent. Luckily he is his only employee, so he won't need to pay wages! Kant charges $1.99 per cup of coffee (tax included). Help Kant out by fixing the bugs in his code!

const gallonOfMilkCost = 2.49;
const bagOfBeansCost = 18.89;
const sackOfSugarCost = 9.99;
const costPerCup = 0.01;
const dailyMaintenanceCost = 30;
const dailyRentCost = 100;

const cupOfCoffeeCost = 1.99;

// takes in the number of cups sold calculates the daily cost of selling that many cups of coffee
// Note: all ingredients go bad at the end of the day!
const dailyCost = (cupsSold) => {
  let gallonsOfMilkUsed = Math.ceil(cupsSold / 100);
  let bagsOfBeansUsed = Math.ceil(cupsSold / 150);
  let sacksOfSugarUsed = Math.ceil(cupsSold / 200);
  return (
    gallonsOfMilkUsed * gallonOfMilkCost +
    bagsOfBeansUsed * bagOfBeansCost +
    sacksOfSugarUsed * sackOfSugarCost +
    cupsSold * costPerCup +
    dailyMaintenanceCost +
    dailyRentCost
  );
};

// takes in the number of cups sold and returns a day's profit
const calculateProfit = (cupsSold) => {
  let cost = dailyCost(cupsSold);
  let revenue = cupOfCoffeeCost * cupsSold;
  return revenue - cost;
};

// return the minimum number of cups to sell in order to reach a profit goal
const reachProfitGoal = (goal) => {
  let cups = 0;
  while (calculateProfit(cups) < goal) {
    cups++;
  }
  return cups;
};

printToScreen(`In order to break even in a day (make $0 in profit), I will need to sell ${reachProfitGoal(0)} cups of coffee.`);

printToScreen(`In order to make a $200 profit in a day, I will need to sell ${reachProfitGoal(200)} cups of coffee.`);

printToScreen(`In order to make a $1000 profit in a day, I will need to sell ${reachProfitGoal(1000)} cups of coffee.`);

