const circumference = (r) => {
  return 2 * Math.PI * r;
};

const circleArea = (r) => {
  return Math.PI * Math.pow(r, 2);
};

const isCircumferenceLarger = (r) => {
  if (circumference(r) > circleArea(r)) {
    return true;
  } else {
    return false;
  }
};

const triangleType = (side1, side2, side3) => {
  if (side1 === side2 && side2 === side3) {
    return "equilateral";
  } else if (side1 === side2 || side2 === side3 || side1 === side3) {
    return "isosceles";
  } else {
    return "scalene";
  }
};

const equilateralTriangleArea = (s) => {
  return Math.pow(s,2) * (Math.sqrt(3) / 4);
}

