/* Program a single-player Rock, Paper, Scissors game! You will need to code the following three functions:

1. Write a function, yourTurn(), which prompts the user to choose Rock, Paper, Scissors and returns their choice in lowercase. If they click cancel, return "nothing". This function will take in no input variables.

2. Write a function, computerTurn(), which randomly returns "rock", "paper", or "scissors". This function will take in no input variables.

3. Write a function, findResult(), which takes in the player choice and computer choice and returns "win", "lose", or "tie" based on the user's results.

The game will continue until either the player or the computer gets 3 wins. Use the alert() function to show the results of each round and printToScreen() to show who won the game.
*/

// Solution

const yourTurn = () => {
  let choice = prompt("Rock, Paper, Scissors?");
  if (choice === null) {
    return "nothing";
  } else {
    return choice.toLowerCase();
  }
};

const computerTurn = () => {
  let choice = Math.floor(Math.random() * 3);
  if (choice === 0) {
    return "rock";
  } else if (choice === 1) {
    return "paper";
  } else {
    return "scissors";
  }
};

const findResult = (playerChoice, computerChoice) => {
  if (playerChoice === computerChoice) {
    return "tie";
  } else if (playerChoice === "rock") {
    if (computerChoice === "scissors") {
      return "win";
    } else {
      return "lose";
    }
  } else if (playerChoice === "paper") {
    if (computerChoice === "rock") {
      return "win";
    } else {
      return "lose";
    }
  } else if (playerChoice === "scissors") {
    if (computerChoice === "paper") {
      return "win";
    } else {
      return "lose";
    }
  } else {
    return "lose";
  }
};

let playerWins = 0;
let computerWins = 0;
let roundNum = 1;

while (playerWins < 3 && computerWins < 3) {
  let pTurn = yourTurn();
  let cTurn = computerTurn();
  let result = findResult(pTurn, cTurn);    
  let message = `Round ${roundNum}: You chose ${pTurn} and the computer chose ${cTurn}!\n`

  if (result === "win") {
    playerWins++;
    message += `You win this round!\nYou now have ${playerWins} points and the computer has ${computerWins} points.`;
  } else if (result === "lose") {
    computerWins++;
    message += `The computer wins this round!\nYou now have ${playerWins} points and the computer has ${computerWins} points.`;
  } else {
    message += `It's a tie!\nYou now have ${playerWins} points and the computer has ${computerWins} points.`;
  }
  alert(message);
  roundNum++;
}

if (playerWins > computerWins) {
  printToScreen("Congratulations! You win!");
} else {
  printToScreen("The computer won. Try again next time!");
}

