  if (savings > 0) {
    return (
      `You should purchase a monthly MetroCard! Your savings will be: $${savings.toFixed(2)}.`);
  } else if (savings < 0) {
    return (
      `You should purchase a pay-per-ride MetroCard! Your savings will be: $${(0 - savings).toFixed(2)}.`);
  } else {
    return "Your cost will be the same either way!";
  }
};

